def add_element(elem, lst=None):
    if lst is None:
        lst = []
    lst.append(elem)
    return lst

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

def factorial(n):
    if n in (0, 1):
        return 1
    return n * factorial(n - 1)
